import { NextResponse } from 'next/server';
import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { generateInvoice } from '@/lib/invoice';

export async function POST() {
  const session = await auth();
  if (!session || session.user.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  // Previous calendar month
  const now = new Date();
  const periodStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  const periodEnd = new Date(now.getFullYear(), now.getMonth(), 1);

  const activeUsers = await prisma.user.findMany({
    where: { role: 'USER', status: 'ACTIVE' },
    select: { id: true },
  });

  // Find users who already have an invoice for this period
  const existing = await prisma.invoice.findMany({
    where: {
      periodStart: { gte: periodStart },
      periodEnd: { lte: periodEnd },
      userId: { in: activeUsers.map(u => u.id) },
    },
    select: { userId: true },
  });
  const alreadyInvoiced = new Set(existing.map(e => e.userId));

  let generated = 0;
  let skipped = 0;
  const errors: Array<{ userId: string; error: string }> = [];

  for (const user of activeUsers) {
    if (alreadyInvoiced.has(user.id)) {
      skipped++;
      continue;
    }

    try {
      const invoice = await generateInvoice(user.id, periodStart, periodEnd, {
        isAutoGenerated: true,
      });
      await prisma.notification.create({
        data: {
          userId: user.id,
          type: 'INVOICE_GENERATED',
          title: 'New Invoice',
          message: `Invoice ${invoice.invoiceNumber} has been generated for $${Number(invoice.total).toFixed(2)}.`,
          link: '/billing',
        },
      });
      generated++;
    } catch (err) {
      errors.push({ userId: user.id, error: String(err) });
    }
  }

  return NextResponse.json({ generated, skipped, errors });
}
