import { prisma } from '@/lib/prisma';
import { Prisma } from '@prisma/client';

function pad(n: number, width = 3): string {
  return String(n).padStart(width, '0');
}

const MONTH_ABBR = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];

async function generateInvoiceNumber(year: number, monthIndex: number): Promise<string> {
  const mon = MONTH_ABBR[monthIndex];
  const prefix = `INV-${year}-${mon}-`;
  const count = await prisma.invoice.count({
    where: { invoiceNumber: { startsWith: prefix } },
  });
  return `${prefix}${pad(count + 1)}`;
}

export async function generateInvoice(
  userId: string,
  periodStart: Date,
  periodEnd: Date,
  options: { notes?: string; isAutoGenerated?: boolean } = {}
) {
  // 1. Fetch user agents
  const userAgents = await prisma.userAgent.findMany({
    where: { userId },
    include: {
      agent: { select: { name: true, retellAgentId: true } },
    },
  });

  type LineItemInput = {
    type: 'SETUP_FEE' | 'MONTHLY_FEE' | 'USAGE_FEE';
    agentId: string;
    agentName: string;
    description: string;
    quantity: Prisma.Decimal;
    unitPrice: Prisma.Decimal;
    total: Prisma.Decimal;
  };

  const lineItems: LineItemInput[] = [];
  const setupFeePaidUpdates: string[] = []; // userAgent IDs to mark setupFeePaid

  for (const ua of userAgents) {
    const agentName = ua.agent.name;
    const agentId = ua.agentId;

    // a. Setup fee (only if not yet paid)
    if (ua.setupFee && ua.setupFee.greaterThan(0) && !ua.setupFeePaid) {
      lineItems.push({
        type: 'SETUP_FEE',
        agentId,
        agentName,
        description: `Agent Setup: ${agentName}`,
        quantity: new Prisma.Decimal(1),
        unitPrice: ua.setupFee,
        total: ua.setupFee.toDecimalPlaces(2),
      });
      setupFeePaidUpdates.push(ua.id);
    }

    // b. Monthly fee
    if (ua.monthlyFee && ua.monthlyFee.greaterThan(0)) {
      lineItems.push({
        type: 'MONTHLY_FEE',
        agentId,
        agentName,
        description: `Monthly Service: ${agentName}`,
        quantity: new Prisma.Decimal(1),
        unitPrice: ua.monthlyFee,
        total: ua.monthlyFee.toDecimalPlaces(2),
      });
    }

    // c. Usage fee
    if (ua.customPrice && ua.customPrice.greaterThan(0)) {
      const effectiveStart = ua.assignedAt > periodStart ? ua.assignedAt : periodStart;

      const result = await prisma.call.aggregate({
        _sum: { durationMs: true },
        where: {
          agentId: ua.agent.retellAgentId,
          startTimestamp: { gte: effectiveStart, lt: periodEnd },
        },
      });

      const totalMs = result._sum.durationMs ?? 0;
      if (totalMs > 0) {
        const totalMinutes = new Prisma.Decimal(totalMs).div(60000).toDecimalPlaces(2);
        if (totalMinutes.greaterThan(0)) {
          const usageTotal = totalMinutes.mul(ua.customPrice).toDecimalPlaces(2);
          lineItems.push({
            type: 'USAGE_FEE',
            agentId,
            agentName,
            description: `Usage: ${agentName} (${totalMinutes.toString()} min)`,
            quantity: totalMinutes,
            unitPrice: ua.customPrice,
            total: usageTotal,
          });
        }
      }
    }
  }

  const subtotal = lineItems.reduce(
    (sum, item) => sum.plus(item.total),
    new Prisma.Decimal(0)
  ).toDecimalPlaces(2);

  const invoiceNumber = await generateInvoiceNumber(
    periodStart.getFullYear(),
    periodStart.getMonth()
  );

  const invoice = await prisma.$transaction(async (tx) => {
    const inv = await tx.invoice.create({
      data: {
        invoiceNumber,
        userId,
        periodStart,
        periodEnd,
        status: 'PENDING',
        subtotal,
        total: subtotal,
        notes: options.notes,
        isAutoGenerated: options.isAutoGenerated ?? false,
        lineItems: {
          create: lineItems.map(item => ({
            type: item.type,
            agentId: item.agentId,
            agentName: item.agentName,
            description: item.description,
            quantity: item.quantity,
            unitPrice: item.unitPrice,
            total: item.total,
          })),
        },
      },
      include: { lineItems: true },
    });

    // Mark setup fees as paid
    if (setupFeePaidUpdates.length > 0) {
      await tx.userAgent.updateMany({
        where: { id: { in: setupFeePaidUpdates } },
        data: { setupFeePaid: true },
      });
    }

    return inv;
  });

  return invoice;
}
